INSERT OR REPLACE INTO challenges (id, format, venue_name, venue_country, pitch_type, title, narrative_intro, constraints_json) VALUES ('ch_odi_ahmedabad', 'ODI', 'Narendra Modi Stadium, Ahmedabad', 'IND', 'SLOW_LOW', 'World Cup 50-Over Crucible', '50 overs under scorching sun. Overs 11-40 strike rotation and reverse swing will decide the match.', '[{"type":"max_per_country","value":2,"exceptions":{"IND":3}},{"type":"min_category","category":"PACE","count":2},{"type":"min_category","category":"SPIN","count":1}]');
