INSERT OR REPLACE INTO challenges (id, format, venue_name, venue_country, pitch_type, title, narrative_intro, constraints_json) VALUES ('ch_test_lords', 'TEST', 'Lord''s Cricket Ground, London', 'ENG', 'GREEN_SEAMER', 'The Ashes at Lord''s - Day 1 Seam Battle', 'Red Dukes ball, emerald green pitch with Lord''s slope. Swing bowlers like Anderson rule the morning session.', '[{"type":"max_per_country","value":2,"exceptions":{"ENG":3}},{"type":"min_category","category":"PACE","count":3},{"type":"batting_hand_order","positions":[1,2],"hand":"LHB"}]');
